    busy=true;
    let now=performance.now(),recent=s.samples.filter(p=>now-p.t<=120);
    let vx=recent.length>1?(recent[recent.length-1].x-recent[0].x)/Math.max(1,recent[recent.length-1].t-recent[0].t):0;
